1110:   position: absolute;
1111:   left: 50%;
1112:   bottom: 1rem;
1113:   transform: translateX(-50%);
1114:   width: min(56%, 560px);
1115:   min-width: 320px;
1116:   height: 120px;
1117:   border: none;
1118:   background: transparent;
1119:   backdrop-filter: none;
1120:   border-radius: 4px;
