40: export function pickPickPopupAnchor(
41:   map: mapboxgl.Map,
42:   e: mapboxgl.MapMouseEvent | mapboxgl.MapLayerMouseEvent,
43: ): "top" | "bottom" | "left" | "right" {
44:   const canvas = map.getCanvas();
45:   const w = Math.max(1, canvas.clientWidth);
46:   const h = Math.max(1, canvas.clientHeight);
47:   const { x, y } = e.point;
48:   const m = Math.min(80, w * 0.14, h * 0.13);
49:   if (y < m) return "top";
50:   if (y > h - m) return "bottom";
51:   if (x < m) return "left";
52:   if (x > w - m) return "right";
53:   return "bottom";
54: }
