144: function isWaypointSlotEnabled(currentCount: number, slot: 0 | 1 | 2): boolean {
145:   if (slot < currentCount) return true;
146:   if (slot === currentCount && currentCount < MAX_ROUTE_WAYPOINTS) return true;
147:   return false;
148: }
149: 
150: function waypointSlotTitle(slot: 0 | 1 | 2, count: number): string {
151:   if (isWaypointSlotEnabled(count, slot)) {
152:     return slot < count
153:       ? `Move waypoint ${slot + 1} here`
154:       : `Add waypoint ${slot + 1} here`;
155:   }
156:   if (slot > count) {
157:     return `Set WP${count + 1} before WP${slot + 1}`;
158:   }
159:   return "No more waypoints";
160: }
