189: export function tryOpenActivityWorldPinPopup(
190:   map: mapboxgl.Map,
191:   event: mapboxgl.MapMouseEvent,
192:   getLabel: (publicationId: string, kind: "pulse" | "heat") => string | null,
193:   popupRef: { current: mapboxgl.Popup | null },
194:   pickAnchor: (map: mapboxgl.Map, event: mapboxgl.MapMouseEvent) => mapboxgl.Anchor,
195: ): boolean {
196:   const layers = [ACTIVITY_PULSE_DOTS_LAYER, ACTIVITY_HEAT_DOTS_LAYER].filter((id) =>
197:     map.getLayer(id),
198:   );
199:   if (!layers.length) return false;
200:   const features = map.queryRenderedFeatures(event.point, { layers });
201:   if (!features.length) return false;
202:   const hit = features[0];
203:   const publicationId = hit.properties?.publicationId;
204:   if (typeof publicationId !== "string" || !publicationId.trim()) return false;
205:   const kind: "pulse" | "heat" = hit.layer?.id === ACTIVITY_HEAT_DOTS_LAYER ? "heat" : "pulse";
206:   const label = getLabel(publicationId.trim(), kind);
207:   if (!label) return false;
208: 
209:   popupRef.current?.remove();
210:   const popup = new mapboxgl.Popup({
211:     closeOnClick: true,
212:     className: "map-view__activity-popup-wrap",
213:     maxWidth: "min(16rem, calc(100vw - 1.5rem))",
214:     anchor: pickAnchor(map, event),
215:     offset: 12,
216:   })
217:     .setLngLat(event.lngLat)
218:     .setDOMContent(buildActivityWorldPopupElement(label, kind))
219:     .addTo(map);
220:   popup.on("close", () => {
221:     if (popupRef.current === popup) popupRef.current = null;
222:   });
223:   popupRef.current = popup;
224:   return true;
225: }
