.map-view__pick-distance-chips {
  display: flex;
  gap: 4px;
  flex-wrap: nowrap;
  grid-column: 1 / -1;
  background: #F1F5F9;
  border-radius: 999px;
}

.map-view__pick-distance-chip {
  flex: 1 1 0;
  min-width: 0;
  padding: 4px 0;
  border: 1px solid transparent;
